-- Cycling library tidy-up, 2026-10-26.
-- 1. Rides within 3 minutes of 45 / 60 / 75 / 90 min are nudged onto that time by trimming or
--    padding warm-up, recovery or cool-down. Main sets are unchanged. Ids stay the same, so plans
--    (training_plans.weeks reference rides by workoutId only) pick up the new lengths with no edits.
-- 2. Two rides that became duplicates of another ride get a distinct variant and name.
-- 3. 15 new prebuilt rides fill gaps in the 45, 60, 75 and 90 min slots.
-- 4. duration_sec is recomputed from steps for every shared ride (17 were NULL).
begin;

-- 47 -> 45: Sprints 8x15s, recoveries 3:45 -> 3:30
update workouts set steps = jsonb_set(steps, '{4,steps,1,duration}', '210') where id = 'prebuilt-anaerobic-45';
-- 48 -> 45: 20-Minute FTP Test, warm-up trimmed by 3 min (opener and test unchanged)
update workouts set steps = jsonb_set(jsonb_set(jsonb_set(steps, '{0,duration}', '240'), '{1,duration}', '240'), '{2,duration}', '120') where id = 'prebuilt-ftptest-20min-48';
-- 45.5 -> 45: Sweet Spot 2x15, cool-down 2:00 -> 1:30
update workouts set steps = jsonb_set(steps, '{6,duration}', '90') where id = 'prebuilt-sweetspot-2x15-45';
-- 57 -> 60: Tempo 3x10, recoveries 4 -> 5 min
update workouts set steps = jsonb_set(steps, '{5,steps,1,duration}', '300') where id = 'prebuilt-tempo-3x10-57';
-- 57 -> 60: VO2 7x3, +1 min warm-up, +2 min cool-down
update workouts set steps = jsonb_set(jsonb_set(steps, '{0,duration}', '300'), '{5,duration}', '420') where id = 'prebuilt-vo2-7x3-57';
-- 58 -> 60: Threshold 6x5, +2 min warm-up
update workouts set steps = jsonb_set(jsonb_set(steps, '{0,duration}', '240'), '{1,duration}', '240') where id = 'prebuilt-threshold-6x5-58';
-- 59 -> 60: Endurance with Standing Efforts, +1 min steady endurance at the end
update workouts set steps = jsonb_set(steps, '{14,duration}', '360') where id = 'prebuilt-endurance-standing-59';
-- 60.5 -> 60: Anaerobic 13x30, cool-down 5:00 -> 4:30
update workouts set steps = jsonb_set(steps, '{5,duration}', '270') where id = 'prebuilt-anaerobic-13x30-61';
-- 63 -> 60: VO2 Max 6x4 (second copy). Keeps its 4 min recoveries so it differs from prebuilt-vo2-60
-- (3:30 recoveries); warm-up and cool-down trimmed instead.
update workouts set name = 'VO2 Max 6x4 Full Recovery',
  steps = jsonb_set(jsonb_set(jsonb_set(steps, '{0,duration}', '180'), '{1,duration}', '120'), '{5,duration}', '240')
  where id = 'prebuilt-vo2-6x4-63';
-- 63 -> 60: Over-Under 4x9, 1 min off each warm-up step and the cool-down
update workouts set steps = jsonb_set(jsonb_set(jsonb_set(steps, '{0,duration}', '180'), '{1,duration}', '180'), '{6,duration}', '240') where id = 'prebuilt-overunder-4x9-63';
-- 73 -> 75: Tempo 2x25, recoveries 4 -> 5 min
update workouts set steps = jsonb_set(steps, '{5,steps,1,duration}', '300') where id = 'prebuilt-tempo-2x25-73';
-- 91 -> 90: Sweet Spot 4x15, cool-down 5 -> 4 min
update workouts set steps = jsonb_set(steps, '{6,duration}', '240') where id = 'prebuilt-sweetspot-90';
-- 92 -> 90: Sweet Spot 3x20 (second copy of prebuilt-sweetspot-90b). Becomes a progressive
-- version, each block a notch harder, with the warm-up trimmed by 2 min.
update workouts set name = 'Sweet Spot 3x20 Progressive',
  steps = '[{"low": 50, "high": 55, "note": "Warm up - easy", "type": "step", "duration": 240, "targetType": "ftp_pct"}, {"low": 60, "high": 65, "note": "Warm up - steady", "type": "step", "duration": 240, "targetType": "ftp_pct"}, {"low": 78, "high": 82, "note": "Warm up - build", "type": "step", "duration": 60, "targetType": "ftp_pct"}, {"low": 100, "high": 105, "note": "Opener burst", "type": "step", "duration": 30, "targetType": "ftp_pct"}, {"low": 50, "high": 55, "note": "Recover", "type": "step", "duration": 30, "targetType": "ftp_pct"}, {"low": 87, "high": 90, "note": "Sweet spot - settle in", "type": "step", "duration": 1200, "targetType": "ftp_pct"}, {"low": 50, "high": 55, "note": "Recover", "type": "step", "duration": 300, "targetType": "ftp_pct"}, {"low": 89, "high": 92, "note": "Sweet spot - a notch up", "type": "step", "duration": 1200, "targetType": "ftp_pct"}, {"low": 50, "high": 55, "note": "Recover", "type": "step", "duration": 300, "targetType": "ftp_pct"}, {"low": 91, "high": 94, "note": "Sweet spot - strongest last", "type": "step", "duration": 1200, "targetType": "ftp_pct"}, {"low": 50, "high": 55, "note": "Recover", "type": "step", "duration": 300, "targetType": "ftp_pct"}, {"low": 45, "high": 50, "note": "Cool down", "type": "step", "duration": 300, "targetType": "ftp_pct"}]'::jsonb
  where id = 'prebuilt-sweetspot-3x20-92';

-- New rides
insert into workouts (id, name, steps, source, category, duration_sec) values
  ('prebuilt-tempo-2x12-45', 'Tempo 2x12', '[{"low": 45, "high": 50, "note": "Warm up - easy", "type": "step", "duration": 240, "targetType": "ftp_pct"}, {"low": 55, "high": 60, "note": "Warm up - steady", "type": "step", "duration": 180, "targetType": "ftp_pct"}, {"low": 65, "high": 70, "note": "Warm up - build", "type": "step", "duration": 60, "targetType": "ftp_pct"}, {"low": 100, "high": 105, "note": "Opener burst", "type": "step", "duration": 30, "targetType": "ftp_pct"}, {"low": 50, "high": 55, "note": "Recover", "type": "step", "duration": 30, "targetType": "ftp_pct"}, {"type": "repeat", "steps": [{"low": 78, "high": 85, "note": "Tempo", "type": "step", "duration": 720, "targetType": "ftp_pct"}, {"low": 55, "high": 60, "note": "Recover", "type": "step", "duration": 180, "targetType": "ftp_pct"}], "repetitions": 2}, {"low": 50, "high": 55, "note": "Cool down", "type": "step", "duration": 360, "targetType": "ftp_pct"}]'::jsonb, 'prebuilt', 'tempo', 2700),
  ('prebuilt-threshold-3x7-45', 'Threshold 3x7', '[{"low": 45, "high": 50, "note": "Warm up - easy", "type": "step", "duration": 240, "targetType": "ftp_pct"}, {"low": 55, "high": 60, "note": "Warm up - steady", "type": "step", "duration": 180, "targetType": "ftp_pct"}, {"low": 75, "high": 80, "note": "Warm up - build", "type": "step", "duration": 60, "targetType": "ftp_pct"}, {"low": 100, "high": 105, "note": "Opener burst", "type": "step", "duration": 30, "targetType": "ftp_pct"}, {"low": 50, "high": 55, "note": "Recover", "type": "step", "duration": 30, "targetType": "ftp_pct"}, {"type": "repeat", "steps": [{"low": 98, "high": 103, "note": "Threshold", "type": "step", "duration": 420, "targetType": "ftp_pct"}, {"low": 50, "high": 55, "note": "Recover", "type": "step", "duration": 180, "targetType": "ftp_pct"}], "repetitions": 3}, {"low": 50, "high": 55, "note": "Cool down", "type": "step", "duration": 360, "targetType": "ftp_pct"}]'::jsonb, 'prebuilt', 'threshold', 2700),
  ('prebuilt-overunder-2x9-45', 'Over-Under 2x9', '[{"low": 45, "high": 50, "note": "Warm up - easy", "type": "step", "duration": 300, "targetType": "ftp_pct"}, {"low": 55, "high": 60, "note": "Warm up - steady", "type": "step", "duration": 180, "targetType": "ftp_pct"}, {"low": 78, "high": 82, "note": "Warm up - build", "type": "step", "duration": 60, "targetType": "ftp_pct"}, {"low": 100, "high": 105, "note": "Opener burst", "type": "step", "duration": 30, "targetType": "ftp_pct"}, {"low": 50, "high": 55, "note": "Recover", "type": "step", "duration": 30, "targetType": "ftp_pct"}, {"type": "repeat", "steps": [{"type": "repeat", "steps": [{"low": 90, "high": 95, "note": "Under", "type": "step", "duration": 90, "targetType": "ftp_pct"}, {"low": 103, "high": 108, "note": "Over", "type": "step", "duration": 90, "targetType": "ftp_pct"}], "repetitions": 3}, {"low": 50, "high": 55, "note": "Recover", "type": "step", "duration": 300, "targetType": "ftp_pct"}], "repetitions": 2}, {"low": 50, "high": 55, "note": "Cool down", "type": "step", "duration": 420, "targetType": "ftp_pct"}]'::jsonb, 'prebuilt', 'over_under', 2700),
  ('prebuilt-endurance-cadence-45', 'Endurance Cadence Drills', '[{"low": 50, "high": 55, "note": "Warm up - easy", "type": "step", "duration": 300, "targetType": "ftp_pct"}, {"low": 60, "high": 68, "note": "Warm up - steady", "type": "step", "duration": 300, "targetType": "ftp_pct"}, {"type": "repeat", "steps": [{"low": 65, "high": 72, "note": "Endurance", "type": "step", "duration": 360, "targetType": "ftp_pct"}, {"low": 70, "high": 75, "note": "High cadence - 100+ rpm, stay smooth", "type": "step", "duration": 60, "targetType": "ftp_pct"}], "repetitions": 4}, {"low": 60, "high": 68, "note": "Endurance - steady", "type": "step", "duration": 120, "targetType": "ftp_pct"}, {"low": 45, "high": 50, "note": "Cool down", "type": "step", "duration": 300, "targetType": "ftp_pct"}]'::jsonb, 'prebuilt', 'endurance', 2700),
  ('prebuilt-threshold-2x15-60', 'Threshold 2x15', '[{"low": 45, "high": 50, "note": "Warm up - easy", "type": "step", "duration": 300, "targetType": "ftp_pct"}, {"low": 55, "high": 60, "note": "Warm up - steady", "type": "step", "duration": 300, "targetType": "ftp_pct"}, {"low": 75, "high": 80, "note": "Warm up - build", "type": "step", "duration": 60, "targetType": "ftp_pct"}, {"low": 100, "high": 105, "note": "Opener burst", "type": "step", "duration": 30, "targetType": "ftp_pct"}, {"low": 50, "high": 55, "note": "Recover", "type": "step", "duration": 30, "targetType": "ftp_pct"}, {"type": "repeat", "steps": [{"low": 95, "high": 100, "note": "Threshold", "type": "step", "duration": 900, "targetType": "ftp_pct"}, {"low": 50, "high": 55, "note": "Recover", "type": "step", "duration": 300, "targetType": "ftp_pct"}], "repetitions": 2}, {"low": 50, "high": 55, "note": "Cool down", "type": "step", "duration": 480, "targetType": "ftp_pct"}]'::jsonb, 'prebuilt', 'threshold', 3600),
  ('prebuilt-anaerobic-30-30-2x6-60', 'Anaerobic 30/30 2x6', '[{"low": 45, "high": 50, "note": "Warm up - easy", "type": "step", "duration": 240, "targetType": "ftp_pct"}, {"low": 55, "high": 60, "note": "Warm up - steady", "type": "step", "duration": 180, "targetType": "ftp_pct"}, {"low": 70, "high": 75, "note": "Warm up - build", "type": "step", "duration": 120, "targetType": "ftp_pct"}, {"low": 95, "high": 100, "note": "Opener burst", "type": "step", "duration": 60, "targetType": "ftp_pct"}, {"low": 50, "high": 55, "note": "Recover", "type": "step", "duration": 60, "targetType": "ftp_pct"}, {"type": "repeat", "steps": [{"type": "repeat", "steps": [{"low": 130, "high": 150, "note": "Anaerobic", "type": "step", "duration": 30, "targetType": "ftp_pct"}, {"low": 50, "high": 55, "note": "Recover", "type": "step", "duration": 30, "targetType": "ftp_pct"}], "repetitions": 6}, {"low": 50, "high": 55, "note": "Recover", "type": "step", "duration": 600, "targetType": "ftp_pct"}], "repetitions": 2}, {"low": 65, "high": 72, "note": "Endurance - steady", "type": "step", "duration": 600, "targetType": "ftp_pct"}, {"low": 50, "high": 55, "note": "Cool down", "type": "step", "duration": 420, "targetType": "ftp_pct"}]'::jsonb, 'prebuilt', 'anaerobic', 3600),
  ('prebuilt-threshold-3x15-75', 'Threshold 3x15', '[{"low": 45, "high": 50, "note": "Warm up - easy", "type": "step", "duration": 300, "targetType": "ftp_pct"}, {"low": 55, "high": 60, "note": "Warm up - steady", "type": "step", "duration": 300, "targetType": "ftp_pct"}, {"low": 75, "high": 80, "note": "Warm up - build", "type": "step", "duration": 60, "targetType": "ftp_pct"}, {"low": 100, "high": 105, "note": "Opener burst", "type": "step", "duration": 30, "targetType": "ftp_pct"}, {"low": 50, "high": 55, "note": "Recover", "type": "step", "duration": 30, "targetType": "ftp_pct"}, {"type": "repeat", "steps": [{"low": 95, "high": 100, "note": "Threshold", "type": "step", "duration": 900, "targetType": "ftp_pct"}, {"low": 50, "high": 55, "note": "Recover", "type": "step", "duration": 240, "targetType": "ftp_pct"}], "repetitions": 3}, {"low": 50, "high": 55, "note": "Cool down", "type": "step", "duration": 360, "targetType": "ftp_pct"}]'::jsonb, 'prebuilt', 'threshold', 4500),
  ('prebuilt-vo2-5x5-75', 'VO2 Max 5x5', '[{"low": 45, "high": 50, "note": "Warm up - easy", "type": "step", "duration": 240, "targetType": "ftp_pct"}, {"low": 55, "high": 60, "note": "Warm up - steady", "type": "step", "duration": 180, "targetType": "ftp_pct"}, {"low": 70, "high": 75, "note": "Warm up - build", "type": "step", "duration": 120, "targetType": "ftp_pct"}, {"low": 95, "high": 100, "note": "Opener burst", "type": "step", "duration": 60, "targetType": "ftp_pct"}, {"type": "repeat", "steps": [{"low": 108, "high": 115, "note": "VO2 max", "type": "step", "duration": 300, "targetType": "ftp_pct"}, {"low": 50, "high": 55, "note": "Recover", "type": "step", "duration": 300, "targetType": "ftp_pct"}], "repetitions": 5}, {"low": 65, "high": 72, "note": "Endurance - steady", "type": "step", "duration": 600, "targetType": "ftp_pct"}, {"low": 50, "high": 55, "note": "Cool down", "type": "step", "duration": 300, "targetType": "ftp_pct"}]'::jsonb, 'prebuilt', 'vo2max', 4500),
  ('prebuilt-overunder-3x15-75', 'Over-Under 3x15', '[{"low": 45, "high": 50, "note": "Warm up - easy", "type": "step", "duration": 240, "targetType": "ftp_pct"}, {"low": 55, "high": 60, "note": "Warm up - steady", "type": "step", "duration": 240, "targetType": "ftp_pct"}, {"low": 78, "high": 82, "note": "Warm up - build", "type": "step", "duration": 60, "targetType": "ftp_pct"}, {"low": 100, "high": 105, "note": "Opener burst", "type": "step", "duration": 30, "targetType": "ftp_pct"}, {"low": 50, "high": 55, "note": "Recover", "type": "step", "duration": 30, "targetType": "ftp_pct"}, {"type": "repeat", "steps": [{"type": "repeat", "steps": [{"low": 90, "high": 95, "note": "Under", "type": "step", "duration": 120, "targetType": "ftp_pct"}, {"low": 103, "high": 108, "note": "Over", "type": "step", "duration": 60, "targetType": "ftp_pct"}], "repetitions": 5}, {"low": 50, "high": 55, "note": "Recover", "type": "step", "duration": 300, "targetType": "ftp_pct"}], "repetitions": 3}, {"low": 50, "high": 55, "note": "Cool down", "type": "step", "duration": 300, "targetType": "ftp_pct"}]'::jsonb, 'prebuilt', 'over_under', 4500),
  ('prebuilt-endurance-steady-75', 'Endurance Steady 75', '[{"low": 50, "high": 55, "note": "Warm up - easy", "type": "step", "duration": 300, "targetType": "ftp_pct"}, {"low": 60, "high": 68, "note": "Warm up - steady", "type": "step", "duration": 300, "targetType": "ftp_pct"}, {"low": 65, "high": 72, "note": "Endurance - steady", "type": "step", "duration": 3300, "targetType": "ftp_pct"}, {"low": 60, "high": 65, "note": "Endurance - easing off", "type": "step", "duration": 300, "targetType": "ftp_pct"}, {"low": 45, "high": 50, "note": "Cool down", "type": "step", "duration": 300, "targetType": "ftp_pct"}]'::jsonb, 'prebuilt', 'endurance', 4500),
  ('prebuilt-threshold-4x12-90', 'Threshold 4x12', '[{"low": 45, "high": 50, "note": "Warm up - easy", "type": "step", "duration": 300, "targetType": "ftp_pct"}, {"low": 55, "high": 60, "note": "Warm up - steady", "type": "step", "duration": 300, "targetType": "ftp_pct"}, {"low": 75, "high": 80, "note": "Warm up - build", "type": "step", "duration": 60, "targetType": "ftp_pct"}, {"low": 100, "high": 105, "note": "Opener burst", "type": "step", "duration": 30, "targetType": "ftp_pct"}, {"low": 50, "high": 55, "note": "Recover", "type": "step", "duration": 30, "targetType": "ftp_pct"}, {"type": "repeat", "steps": [{"low": 95, "high": 100, "note": "Threshold", "type": "step", "duration": 720, "targetType": "ftp_pct"}, {"low": 50, "high": 55, "note": "Recover", "type": "step", "duration": 300, "targetType": "ftp_pct"}], "repetitions": 4}, {"low": 65, "high": 72, "note": "Endurance - steady", "type": "step", "duration": 300, "targetType": "ftp_pct"}, {"low": 50, "high": 55, "note": "Cool down", "type": "step", "duration": 300, "targetType": "ftp_pct"}]'::jsonb, 'prebuilt', 'threshold', 5400),
  ('prebuilt-overunder-4x12-90', 'Over-Under 4x12', '[{"low": 45, "high": 50, "note": "Warm up - easy", "type": "step", "duration": 300, "targetType": "ftp_pct"}, {"low": 55, "high": 60, "note": "Warm up - steady", "type": "step", "duration": 300, "targetType": "ftp_pct"}, {"low": 78, "high": 82, "note": "Warm up - build", "type": "step", "duration": 60, "targetType": "ftp_pct"}, {"low": 100, "high": 105, "note": "Opener burst", "type": "step", "duration": 30, "targetType": "ftp_pct"}, {"low": 50, "high": 55, "note": "Recover", "type": "step", "duration": 30, "targetType": "ftp_pct"}, {"type": "repeat", "steps": [{"type": "repeat", "steps": [{"low": 90, "high": 95, "note": "Under", "type": "step", "duration": 120, "targetType": "ftp_pct"}, {"low": 103, "high": 108, "note": "Over", "type": "step", "duration": 60, "targetType": "ftp_pct"}], "repetitions": 4}, {"low": 50, "high": 55, "note": "Recover", "type": "step", "duration": 300, "targetType": "ftp_pct"}], "repetitions": 4}, {"low": 65, "high": 72, "note": "Endurance - steady", "type": "step", "duration": 300, "targetType": "ftp_pct"}, {"low": 50, "high": 55, "note": "Cool down", "type": "step", "duration": 300, "targetType": "ftp_pct"}]'::jsonb, 'prebuilt', 'over_under', 5400),
  ('prebuilt-vo2-5x4-endurance-90', 'VO2 Max 5x4 + Endurance', '[{"low": 45, "high": 50, "note": "Warm up - easy", "type": "step", "duration": 240, "targetType": "ftp_pct"}, {"low": 55, "high": 60, "note": "Warm up - steady", "type": "step", "duration": 180, "targetType": "ftp_pct"}, {"low": 70, "high": 75, "note": "Warm up - build", "type": "step", "duration": 120, "targetType": "ftp_pct"}, {"low": 95, "high": 100, "note": "Opener burst", "type": "step", "duration": 60, "targetType": "ftp_pct"}, {"type": "repeat", "steps": [{"low": 112, "high": 118, "note": "VO2 max", "type": "step", "duration": 240, "targetType": "ftp_pct"}, {"low": 50, "high": 55, "note": "Recover", "type": "step", "duration": 240, "targetType": "ftp_pct"}], "repetitions": 5}, {"low": 65, "high": 72, "note": "Endurance - steady", "type": "step", "duration": 2100, "targetType": "ftp_pct"}, {"low": 50, "high": 55, "note": "Cool down", "type": "step", "duration": 300, "targetType": "ftp_pct"}]'::jsonb, 'prebuilt', 'vo2max', 5400),
