  ('prebuilt-endurance-cadence-90', 'Long Endurance Cadence Drills', '[{"low": 50, "high": 55, "note": "Warm up - easy", "type": "step", "duration": 300, "targetType": "ftp_pct"}, {"low": 60, "high": 68, "note": "Warm up - steady", "type": "step", "duration": 300, "targetType": "ftp_pct"}, {"type": "repeat", "steps": [{"low": 65, "high": 72, "note": "Endurance", "type": "step", "duration": 600, "targetType": "ftp_pct"}, {"low": 70, "high": 75, "note": "High cadence - 100+ rpm, stay smooth", "type": "step", "duration": 60, "targetType": "ftp_pct"}], "repetitions": 6}, {"low": 60, "high": 68, "note": "Endurance - steady", "type": "step", "duration": 540, "targetType": "ftp_pct"}, {"low": 45, "high": 50, "note": "Cool down", "type": "step", "duration": 300, "targetType": "ftp_pct"}]'::jsonb, 'prebuilt', 'endurance', 5400)
on conflict (id) do nothing;

-- duration_sec from steps for every shared ride
with recursive t(id, el, mult) as (
  select w.id, e, 1 from workouts w, jsonb_array_elements(w.steps) e where w.user_id is null
  union all
  select t.id, x, t.mult * (t.el->>'repetitions')::int from t, jsonb_array_elements(t.el->'steps') x where t.el->>'type' = 'repeat'
), d as (
  select id, sum(case when el->>'type' = 'repeat' then 0 else coalesce((el->>'duration')::int, 0) * mult end)::int as sec from t group by id
)
update workouts w set duration_sec = d.sec from d where w.id = d.id and w.duration_sec is distinct from d.sec;

commit;
